local QuadrantMaker = {}
local PRODUCTS = {
    simple_wooden_quadrant = { name = "Preprost leseni kvadrant", woodCost = 2, time = 3, cost = 35, navigation = 15, education = 10, happiness = 1, description = "Preprost leseni kvadrant za navigacijo." },
    brass_graduated_quadrant = { name = "Medeninast merjeni kvadrant", woodCost = 2, brassCost = 2, time = 6, cost = 120, navigation = 28, education = 22, happiness = 1, prestige = 2, description = "Medeninast merjeni kvadrant za trgovce." },
    marble_arc_quadrant = { name = "Marmornatolok kvadrant", woodCost = 2, marbleCost = 2, brassCost = 1, time = 9, cost = 300, navigation = 42, education = 35, happiness = 2, prestige = 5, description = "Marmornatolok kvadrant za plemiče." },
    silver_plumb_quadrant = { name = "Srebrnoprotežni kvadrant", woodCost = 2, silverCost = 2, brassCost = 1, marbleCost = 1, time = 13, cost = 720, navigation = 58, education = 48, happiness = 3, prestige = 13, description = "Srebrnoprotežni kvadrant za visoke plemiče." },
    gold_inlaid_quadrant = { name = "Zlatovloženi kvadrant", woodCost = 2, goldCost = 2, silverCost = 1, brassCost = 1, marbleCost = 1, jewelCost = 1, time = 17, cost = 1600, navigation = 74, education = 62, happiness = 5, prestige = 26, description = "Zlatovloženi kvadrant z draguljem za visoko plemstvo." },
    royal_grand_quadrant = { name = "Kraljevski veliki kvadrant", woodCost = 3, goldCost = 3, silverCost = 2, brassCost = 1, marbleCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 3700, navigation = 90, education = 85, happiness = 12, prestige = 58, description = "Veliki kraljevski kvadrant z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    quadrant_workshop = { name = "Kvadrantna delavnica", cost = { gold = 220, wood = 120, stone = 100, brass = 6 }, upkeep = 5, qualityBonus = 5 },
    geometry_loft = { name = "Geometrijska podstrešje", cost = { gold = 800, wood = 240, stone = 240, marble = 4, brass = 8 }, upkeep = 18, qualityBonus = 18 },
    master_instrument_atelier = { name = "Mojstrski inštrumentni atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_quadrant_palace = { name = "Kraljevska kvadrantna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
QuadrantMaker.woodStock = 16; QuadrantMaker.brassStock = 12; QuadrantMaker.marbleStock = 10; QuadrantMaker.silverStock = 6; QuadrantMaker.goldStock = 6; QuadrantMaker.jewelStock = 4; QuadrantMaker.pearlStock = 4
QuadrantMaker.productStock = {}; QuadrantMaker.buildings = {}; QuadrantMaker.maker = nil; QuadrantMaker.activeMaking = {}; QuadrantMaker.totalProducts = 0; QuadrantMaker.dayTimer = 0
function QuadrantMaker.init() QuadrantMaker.woodStock=16; QuadrantMaker.brassStock=12; QuadrantMaker.marbleStock=10; QuadrantMaker.silverStock=6; QuadrantMaker.goldStock=6; QuadrantMaker.jewelStock=4; QuadrantMaker.pearlStock=4; QuadrantMaker.productStock={}; QuadrantMaker.buildings={}; QuadrantMaker.maker=nil; QuadrantMaker.activeMaking={}; QuadrantMaker.totalProducts=0; QuadrantMaker.dayTimer=0; print("[QuadrantMaker] Royal Quadrant Maker System initialized (6 products, 4 buildings)") end
function QuadrantMaker.hireMaker(n,s) s=s or math.random(55,90); local c=480+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuadrantMaker.maker={name=n or ("Kvadrantar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kvadrantar najet: %s (spretnost: %d)",QuadrantMaker.maker.name,s),"success") end; return true end
function QuadrantMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuadrantMaker.build(id) local ok,e=QuadrantMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuadrantMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuadrantMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuadrantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuadrantMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and QuadrantMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.brassCost and QuadrantMaker.brassStock<(d.brassCost or 0) then return false,"Premalo medenine" end; if d.marbleCost and QuadrantMaker.marbleStock<(d.marbleCost or 0) then return false,"Premalo marmorja" end; if d.silverCost and QuadrantMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuadrantMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuadrantMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuadrantMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuadrantMaker.buildings==0 then return false,"Potrebna kvadrantna delavnica" end; if not QuadrantMaker.maker then return false,"Potreben kvadrantar" end; return true end
function QuadrantMaker.make(pt,qty) qty=qty or 1; local ok,e=QuadrantMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then QuadrantMaker.woodStock=QuadrantMaker.woodStock-d.woodCost*qty end; if d.brassCost then QuadrantMaker.brassStock=QuadrantMaker.brassStock-d.brassCost*qty end; if d.marbleCost then QuadrantMaker.marbleStock=QuadrantMaker.marbleStock-d.marbleCost*qty end; if d.silverCost then QuadrantMaker.silverStock=QuadrantMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuadrantMaker.goldStock=QuadrantMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuadrantMaker.jewelStock=QuadrantMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuadrantMaker.pearlStock=QuadrantMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuadrantMaker.maker then t=math.max(1,t-math.floor(QuadrantMaker.maker.skill/13)) end; table.insert(QuadrantMaker.activeMaking,{id="quadrant_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,navigation=d.navigation or 0,education=d.education or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuadrantMaker.completeMaking(m) local q=1.0+(QuadrantMaker.getQualityBonus()/100); if QuadrantMaker.maker then q=q+(QuadrantMaker.maker.skill/150) end; q=math.min(2.4,q); QuadrantMaker.productStock[m.productType]=(QuadrantMaker.productStock[m.productType] or 0)+m.quantity; QuadrantMaker.totalProducts=QuadrantMaker.totalProducts+m.quantity; if m.navigation>0 and _G.state then _G.state.navigation=(_G.state.navigation or 0)+m.navigation end; if m.education>0 and _G.state then _G.state.education=(_G.state.education or 0)+m.education end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuadrantMaker.maker then QuadrantMaker.maker.itemsMade=QuadrantMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuadrantMaker.maker.skill=math.min(100,QuadrantMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kvadrant izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quadrant.completed",{productName=m.productName,navigation=m.navigation,education=m.education,prestige=m.prestige,happiness=m.happiness}) end end
function QuadrantMaker.update(dt) if not _G.state then return end; QuadrantMaker.dayTimer=QuadrantMaker.dayTimer+dt; if QuadrantMaker.dayTimer>=30 then QuadrantMaker.dayTimer=0; for i=#QuadrantMaker.activeMaking,1,-1 do local m=QuadrantMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuadrantMaker.completeMaking(m); table.remove(QuadrantMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuadrantMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuadrantMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuadrantMaker.getStats() return {woodStock=QuadrantMaker.woodStock,brassStock=QuadrantMaker.brassStock,marbleStock=QuadrantMaker.marbleStock,silverStock=QuadrantMaker.silverStock,goldStock=QuadrantMaker.goldStock,jewelStock=QuadrantMaker.jewelStock,pearlStock=QuadrantMaker.pearlStock,productStock=QuadrantMaker.productStock,numBuildings=#QuadrantMaker.buildings,hasMaker=QuadrantMaker.maker~=nil,makerName=QuadrantMaker.maker and QuadrantMaker.maker.name or "—",makerSkill=QuadrantMaker.maker and QuadrantMaker.maker.skill or 0,activeMaking=#QuadrantMaker.activeMaking,totalProducts=QuadrantMaker.totalProducts} end
return QuadrantMaker
